const lessons=[];
function L(id,level,title,goal,rule,example,text,questions,task,model,words){lessons.push({id,level,title,goal,rule,example,text,questions,task,model,words});}
const Q=(q,options,answer,why)=>({q,options,answer,why});
L('ankommen','A1','Hallo, das bin ich.','Du stellst dich vor und fragst nach persönlichen Angaben.','Das Verb steht im Aussagesatz auf Position 2. Bei W-Fragen steht zuerst das Fragewort. sein: ich bin, du bist, er/sie ist, wir sind, ihr seid, sie/Sie sind.','Ich komme aus Syrien. Wo wohnen Sie?','Hallo! Ich heiße Samira. Ich komme aus Syrien und wohne jetzt in Hagen. Ich bin 29 Jahre alt. Meine Muttersprache ist Arabisch. Ich lerne Deutsch am Vormittag.',[Q('Wo wohnt Samira jetzt?',['In Syrien','In Hagen','In Berlin'],1,'„Ich wohne jetzt in Hagen“ nennt den aktuellen Wohnort.'),Q('Ergänze: Wo … du?',['wohnt','wohnen','wohnst'],2,'Bei „du“ hat wohnen die Endung -st: du wohnst.'),Q('Welcher Satz ist richtig?',['Ich bin 29 Jahre alt.','Ich 29 Jahre bin alt.','Ich sein 29 Jahre alt.'],0,'Das konjugierte Verb „bin“ steht auf Position 2.')],'Schreibe vier Sätze über dich: Name, Herkunft, Wohnort und Sprachen.','Ich heiße Alex. Ich komme aus Rumänien. Ich wohne in Gevelsberg. Ich spreche Rumänisch und lerne Deutsch.',['der Name','wohnen','die Sprache']);
L('einkaufen','A1','Einmal Brot, bitte.','Du kaufst Lebensmittel ein und fragst nach Preisen.','Artikel gehören zum Nomen: der Apfel, die Milch, das Brot. Im Akkusativ wird der/ein zu den/einen. Die anderen Formen bleiben gleich.','Ich kaufe einen Apfel, eine Banane und ein Brot.','Im Laden kostet ein Brot 2,80 Euro. Ein Liter Milch kostet 1,20 Euro. Ein Kilo Äpfel kostet 2,50 Euro. Heute kauft Leo ein Brot und einen Liter Milch.',[Q('Wie viel bezahlt Leo?',['2,80 Euro','4,00 Euro','6,50 Euro'],1,'2,80 Euro für Brot plus 1,20 Euro für Milch sind 4,00 Euro.'),Q('Ich möchte … Apfel.',['ein','eine','einen'],2,'„Apfel“ ist maskulin. Nach „möchte“ steht hier Akkusativ: einen Apfel.'),Q('Welche Frage passt an der Kasse?',['Wie viel kostet das?','Woher kommen Sie?','Wie alt ist das?'],0,'Mit „Wie viel kostet das?“ fragst du nach dem Preis.')],'Schreibe einen kurzen Dialog im Laden: Wunsch, Preisfrage, Antwort, Dank.','Guten Tag, ich möchte ein Brot. Wie viel kostet das? – Das kostet 2,80 Euro. – Danke schön.',['das Brot','kaufen','der Preis']);
L('termine','A1','Zeit für einen Termin.','Du verstehst Uhrzeiten und vereinbarst einen Termin.','Wochentag: am Montag. Uhrzeit: um neun Uhr. Halb zehn bedeutet 9:30 Uhr. Bei Ja/Nein-Fragen steht das Verb an erster Stelle.','Haben Sie am Dienstag um zehn Uhr Zeit?','Die Praxis ist montags bis freitags von 8 bis 12 Uhr geöffnet. Am Donnerstag ist sie zusätzlich von 15 bis 18 Uhr geöffnet. Ihr Termin ist am Donnerstag um halb vier am Nachmittag.',[Q('Wann ist der Termin?',['14:30 Uhr','15:30 Uhr','16:30 Uhr'],1,'„Halb vier“ ist eine halbe Stunde vor vier, also 15:30 Uhr.'),Q('Der Termin ist … Montag … 9 Uhr.',['um / am','am / um','in / an'],1,'Vor dem Wochentag steht „am“, vor der Uhrzeit „um“.'),Q('Ist die Praxis am Samstag geöffnet?',['Ja, vormittags','Ja, nachmittags','Nein'],2,'Die Öffnungszeiten gelten nur von Montag bis Freitag.')],'Bitte schriftlich um einen Termin. Nenne einen Tag und eine Uhrzeit.','Guten Tag, ich möchte einen Termin. Haben Sie am Donnerstag um 16 Uhr Zeit? Vielen Dank.',['der Termin','die Uhr','geöffnet']);
L('wohnen','A1','Hier wohne ich.','Du beschreibst eine Wohnung und verneinst Aussagen.','Mit „kein“ verneinst du Nomen mit unbestimmtem Artikel oder ohne Artikel. Mit „nicht“ verneinst du zum Beispiel ein Adjektiv: Die Wohnung ist nicht groß.','Die Wohnung hat keinen Balkon. Die Küche ist nicht klein.','Mila wohnt in einer kleinen Wohnung. Sie hat zwei Zimmer, eine Küche und ein Bad. Einen Balkon gibt es nicht. Die Wohnung kostet 620 Euro im Monat.',[Q('Wie viele Zimmer hat die Wohnung?',['Zwei','Drei','Vier'],0,'Küche und Bad werden hier zusätzlich zu den zwei Zimmern genannt.'),Q('Die Wohnung hat … Balkon.',['nicht','keinen','keine'],1,'„Balkon“ ist maskulin und steht nach „hat“ im Akkusativ.'),Q('Welcher Satz verneint „Die Küche ist klein“?',['Die Küche ist kein klein.','Die Küche ist nicht klein.','Die Küche nicht ist klein.'],1,'Ein Adjektiv wie „klein“ wird mit „nicht“ verneint.')],'Beschreibe deine Wohnung in vier Sätzen. Nenne auch etwas, das sie nicht hat.','Meine Wohnung hat drei Zimmer. Die Küche ist hell. Die Wohnung hat keinen Garten. Sie ist nicht teuer.',['die Wohnung','das Zimmer','der Balkon']);
L('alltag','A2','Was war gestern?','Du erzählst im Perfekt von deinem Tag.','Perfekt = haben oder sein + Partizip II. Das Hilfsverb steht auf Position 2, das Partizip am Ende. Bei vielen Verben der Ortsveränderung steht sein.','Ich habe gekocht. Danach bin ich nach Hause gefahren.','Gestern hat Pavel bis 16 Uhr gearbeitet. Danach ist er mit dem Bus nach Hause gefahren. Am Abend hat er eine Suppe gekocht und seine Schwester angerufen.',[Q('Was hat Pavel nach der Arbeit gemacht?',['Er ist nach Hause gefahren.','Er hat seine Schwester besucht.','Er hat im Restaurant gegessen.'],0,'Er fährt nach der Arbeit mit dem Bus nach Hause.'),Q('Ich … gestern nach Köln gefahren.',['habe','bin','werde'],1,'„fahren“ mit Ortsveränderung bildet das Perfekt mit „sein“.'),Q('Welches Partizip gehört zu „anrufen“?',['geanruft','anrufen','angerufen'],2,'Beim trennbaren Verb anrufen lautet das Partizip „angerufen“.')],'Schreibe fünf Sätze über gestern. Verwende mindestens einmal „haben“ und einmal „sein“.','Gestern habe ich gelernt. Dann bin ich einkaufen gegangen. Ich habe Gemüse gekauft. Zu Hause habe ich gekocht. Am Abend habe ich einen Film gesehen.',['gestern','arbeiten','anrufen']);
L('gesundheit','A2','Gute Besserung!','Du beschreibst Beschwerden und verstehst Ratschläge.','Modalverben stehen auf Position 2; der Infinitiv steht am Satzende. „sollen“ gibt oft einen Rat oder Auftrag wieder. „müssen“ drückt eine Notwendigkeit aus.','Sie sollen viel trinken. Ich muss den Termin absagen.','Noor ruft in der Praxis an. Sie hat seit zwei Tagen Halsschmerzen. Die Mitarbeiterin bietet einen Termin um 11 Uhr an. Noor soll ihre Versichertenkarte mitbringen.',[Q('Seit wann hat Noor Beschwerden?',['Seit heute','Seit zwei Tagen','Seit zwei Wochen'],1,'Im Text steht „seit zwei Tagen“.'),Q('Was soll Noor mitbringen?',['Ihre Versichertenkarte','Einen Brief','Einen Ausweis ihres Kindes'],0,'Die Mitarbeiterin bittet um die Versichertenkarte.'),Q('Ergänze für Noor: Sie … die Karte mitbringen.',['sollen','sollst','soll'],2,'Für Noor = „sie“ im Singular: soll. Der Infinitiv steht am Ende.')],'Du kannst nicht zum Deutschkurs kommen. Schreibe eine kurze Nachricht mit Grund und Dauer.','Guten Morgen, ich bin krank und kann heute nicht zum Kurs kommen. Ich habe Halsschmerzen. Morgen melde ich mich wieder. Viele Grüße, Noor',['die Schmerzen','mitbringen','krank']);
L('unterwegs','A2','Unterwegs in der Stadt.','Du verstehst Wege und Verkehrsinformationen.','Bei Ortsangaben mit Wechselpräpositionen gilt: Wo? + Dativ; Wohin? + Akkusativ. Nicht jede Bewegung bedeutet Akkusativ: Entscheidend ist ein Zielwechsel.','Ich warte an der Haltestelle. Ich gehe an die Haltestelle.','Wegen Bauarbeiten hält der Bus 542 heute nicht am Rathaus. Bitte gehen Sie zur Haltestelle Poststraße. Sie liegt neben der Apotheke. Die Abfahrtszeiten bleiben gleich.',[Q('Wo fährt der Bus heute ab?',['Am Rathaus','An der Poststraße','Am Bahnhof'],1,'Die Ersatzhaltestelle ist Poststraße.'),Q('Ich warte an … Haltestelle.',['die','der','den'],1,'„Wo?“ verlangt Dativ: an der Haltestelle.'),Q('Was ändert sich laut Text nicht?',['Die Haltestelle','Die Fahrtrichtung','Die Abfahrtszeiten'],2,'Die Abfahrtszeiten bleiben ausdrücklich gleich.')],'Erkläre einer Person den Weg von der Haltestelle zur Apotheke. Erfinde einen einfachen Weg.','Gehen Sie geradeaus und dann nach links. Die Apotheke liegt rechts neben dem Supermarkt. Zu Fuß brauchen Sie ungefähr fünf Minuten.',['die Haltestelle','geradeaus','neben']);
L('schule','A2','Eine Nachricht an die Schule.','Du nennst einen Grund und bittest höflich um Informationen.','Nach „weil“ steht das konjugierte Verb am Ende. Höfliche Bitte: Könnten Sie mir bitte …?','Mein Kind fehlt, weil es krank ist. Könnten Sie mir die Aufgaben schicken?','Liebe Eltern, am Freitag beginnt der Ausflug um 8:15 Uhr am Schultor. Die Kinder brauchen ein Getränk und eine Regenjacke. Um 13 Uhr sind wir zurück. Bitte geben Sie Ihrem Kind kein Geld mit.',[Q('Was sollen die Kinder mitbringen?',['Geld und Essen','Ein Getränk und eine Regenjacke','Nur ein Getränk'],1,'Beide Dinge werden ausdrücklich genannt.'),Q('Mein Sohn fehlt, weil er …',['ist krank','krank ist','krank sein'],1,'Im weil-Satz steht das konjugierte Verb „ist“ am Ende.'),Q('Wann kommen die Kinder zurück?',['Um 8:15 Uhr','Um 12 Uhr','Um 13 Uhr'],2,'Die Rückkehr ist für 13 Uhr angekündigt.')],'Dein Kind kann am Ausflug nicht teilnehmen. Schreibe an die Lehrkraft: Grund, Entschuldigung, Frage nach Aufgaben.','Sehr geehrte Frau Weber, meine Tochter kann am Freitag nicht am Ausflug teilnehmen, weil sie krank ist. Bitte entschuldigen Sie ihr Fehlen. Könnten Sie uns die Aufgaben schicken? Mit freundlichen Grüßen, Elena Marin',['die Schule','der Ausflug','weil']);
L('reklamation','B1','Das möchte ich reklamieren.','Du beschreibst einen Mangel und formulierst eine Bitte.','Relativsätze beschreiben ein Nomen genauer. Das Relativpronomen richtet sich in Genus und Numerus nach dem Nomen; sein Fall hängt von seiner Funktion im Relativsatz ab.','Der Drucker, den ich gekauft habe, funktioniert nicht.','Sie haben vor einer Woche einen Drucker bestellt. Das Paket kam gestern an. Der Drucker lässt sich einschalten, aber er druckt nur leere Seiten. Sie haben die Anleitung gelesen und die Patronen geprüft.',[Q('Was ist das Problem?',['Die Lieferung fehlt.','Der Drucker druckt leere Seiten.','Der Drucker lässt sich nicht einschalten.'],1,'Einschalten ist möglich, aber die Seiten bleiben leer.'),Q('Der Drucker, … ich bestellt habe, ist kaputt.',['der','dem','den'],2,'Im Relativsatz ist der Drucker das Akkusativobjekt von „bestellt habe“.'),Q('Welche Bitte ist sachlich und höflich?',['Schicken Sie mir bitte ein Ersatzgerät.','Sie verkaufen nur Müll!','Ich will sofort alles!'],0,'Eine konkrete höfliche Bitte hilft bei der Klärung.')],'Schreibe eine Reklamation: Kaufdatum, Problem, bisheriger Versuch und gewünschte Lösung.','Sehr geehrte Damen und Herren, vor einer Woche habe ich bei Ihnen einen Drucker bestellt. Leider druckt er nur leere Seiten. Ich habe bereits die Anleitung gelesen und die Patronen überprüft. Bitte schicken Sie mir ein Ersatzgerät. Vielen Dank für Ihre Hilfe. Mit freundlichen Grüßen, Alex Marin',['die Lieferung','der Mangel','ersetzen']);
L('meinung','B1','Ich sehe das so.','Du äußerst deine Meinung und begründest sie.','„obwohl“ leitet einen Nebensatz mit Verb am Ende ein. „trotzdem“ verbindet Hauptsätze: Danach folgt das Verb, wenn trotzdem auf Position 1 steht.','Obwohl ich wenig Zeit habe, lerne ich Deutsch. Ich habe wenig Zeit. Trotzdem lerne ich Deutsch.','Im Kurs wird über digitale Lernangebote diskutiert. Fatima findet kurze Onlineübungen praktisch, weil sie im Bus lernen kann. Boris lernt lieber mit anderen, weil er direkt Fragen stellen möchte. Beide möchten gedruckte Merkblätter behalten.',[Q('Was finden beide wichtig?',['Nur online lernen','Gedruckte Merkblätter behalten','Im Bus lernen'],1,'Dieser Wunsch wird am Ende für beide genannt.'),Q('Ich bin müde. Trotzdem …',['ich lerne weiter.','lerne ich weiter.','weiter ich lerne.'],1,'Nach „trotzdem“ auf Position 1 folgt das Verb „lerne“.'),Q('Welche Formulierung drückt eine Meinung aus?',['Meiner Meinung nach ist das hilfreich.','Der Kurs beginnt um acht Uhr.','Das Buch kostet zehn Euro.'],0,'„Meiner Meinung nach“ kennzeichnet eine persönliche Einschätzung.')],'Was findest du besser: Lernen zu Hause oder im Kurs? Begründe deine Meinung und nenne einen Nachteil.','Meiner Meinung nach ist Lernen im Kurs besonders hilfreich, weil man miteinander sprechen kann. Zu Hause kann ich zwar in meinem Tempo lernen, aber manchmal fehlt mir die Motivation. Deshalb kombiniere ich beides.',['die Meinung','obwohl','trotzdem']);
L('arbeit','B1','Eine Stelle finden.','Du verstehst Stellenanzeigen und beschreibst Erfahrungen.','Mit „um … zu“ drückst du einen Zweck aus, wenn die handelnde Person in beiden Teilen gleich ist. Bei unterschiedlichen Personen passt oft „damit“.','Ich besuche einen Kurs, um mein Deutsch zu verbessern.','Ein Hotel sucht eine Servicekraft für 25 Stunden pro Woche. Arbeitszeiten: morgens und gelegentlich am Wochenende. Erfahrung ist erwünscht, aber nicht notwendig. Bewerbungen bitte bis zum 15. Oktober per E-Mail. Telefonische Bewerbungen sind nicht möglich.',[Q('Ist Berufserfahrung zwingend erforderlich?',['Ja','Nein','Nur am Wochenende'],1,'„Erwünscht, aber nicht notwendig“ bedeutet: Auch ohne Erfahrung ist eine Bewerbung möglich.'),Q('Wie soll man sich bewerben?',['Telefonisch','Persönlich','Per E-Mail'],2,'Die Anzeige nennt ausdrücklich E-Mail.'),Q('Ich lerne Deutsch, … eine Stelle zu finden.',['weil','um','obwohl'],1,'„um … zu“ nennt das Ziel des Lernens.')],'Schreibe eine kurze Bewerbung: Interesse, Erfahrung, Arbeitszeiten und Bitte um ein Gespräch.','Sehr geehrte Damen und Herren, ich interessiere mich für die Stelle als Servicekraft. Ich habe zwei Jahre in einem Café gearbeitet. Ich kann morgens und am Wochenende arbeiten. Über eine Einladung zu einem Gespräch würde ich mich freuen. Mit freundlichen Grüßen, Samira Ali',['die Bewerbung','die Erfahrung','die Stelle']);
L('planen','B1','Zusammen geht mehr.','Du machst Vorschläge und handelst eine gemeinsame Lösung aus.','Höfliche Vorschläge: Wir könnten … / Wie wäre es mit …? Reagiere auf den Vorschlag der anderen Person, bevor du einen neuen machst.','Das ist eine gute Idee. Samstag passt mir leider nicht. Wie wäre es mit Sonntag?','Ihr Kurs möchte ein gemeinsames Frühstück organisieren. Der Raum ist am Freitag ab 10 Uhr frei. Eine Person isst vegan, zwei Personen trinken keinen Kaffee. Das gemeinsame Budget beträgt 40 Euro.',[Q('Welche Idee passt zu den Informationen?',['Nur Käse und Kaffee kaufen','Auch Obst, Brot und Tee anbieten','Für 80 Euro bestellen'],1,'Obst, geeignetes Brot und Tee berücksichtigen unterschiedliche Wünsche und können im Budget liegen.'),Q('Welche Reaktion führt das Gespräch weiter?',['Nein.','Das ist schlecht.','Freitag passt. Wer kauft die Getränke?'],2,'Du reagierst auf die Zeit und klärst anschließend eine Aufgabe.'),Q('Wir … vorher eine Einkaufsliste schreiben.',['könnten','könnte','könntest'],0,'Konjunktiv II von können für „wir“: könnten.')],'Plant zu zweit das Frühstück: Zeitpunkt, Essen, Getränke, Kosten und Aufgaben. Notiere eure Vereinbarung.','Wir treffen uns am Freitag um 10 Uhr. Ich bringe Brot und Obst mit. Du kaufst Tee und Saft. Jede Person gibt vier Euro dazu. Vorher fragen wir nach Allergien.',['der Vorschlag','vereinbaren','die Aufgabe']);
L('bewerbung-b2','B2','Beruflich weiterkommen.','Du beschreibst Kompetenzen und begründest deine Eignung.','Verb-Nomen-Verbindungen machen berufliche Texte präzise: Verantwortung übernehmen, Erfahrung sammeln, eine Entscheidung treffen. Nenne zu jeder Stärke ein konkretes Beispiel.','Ich habe die Einarbeitung neuer Mitarbeitender übernommen.','Gesucht wird eine Teamassistenz. Zu den Aufgaben gehören Terminplanung, Korrespondenz und Vorbereitung von Besprechungen. Vorausgesetzt werden sichere Deutschkenntnisse und ein sorgfältiger Arbeitsstil. Erfahrung mit Tabellenkalkulation ist von Vorteil, aber keine Voraussetzung.',[Q('Welche Fähigkeit ist ein Vorteil, aber keine Pflicht?',['Sorgfältiges Arbeiten','Tabellenkalkulation','Sichere Deutschkenntnisse'],1,'„Von Vorteil, aber keine Voraussetzung“ bezieht sich auf Tabellenkalkulation.'),Q('Welche Verbindung ist korrekt?',['Verantwortung machen','Verantwortung treffen','Verantwortung übernehmen'],2,'Die übliche Verbindung lautet „Verantwortung übernehmen“.'),Q('Welche Aussage belegt eine Kompetenz konkret?',['Ich bin sehr gut.','Ich habe die Termine eines Teams mit acht Personen koordiniert.','Ich kann alles.'],1,'Die konkrete Aufgabe und die Teamgröße machen die Erfahrung nachvollziehbar.')],'Stelle deinen beruflichen Weg vor: Ausbildung, Erfahrung, Stärke mit Beispiel und berufliches Ziel.','Nach meiner Ausbildung habe ich drei Jahre in der Verwaltung gearbeitet. Dort war ich für die Terminplanung zuständig. Besonders gut kann ich Abläufe organisieren. Beispielsweise habe ich ein gemeinsames Buchungssystem für unser Team eingeführt. Künftig möchte ich mehr Verantwortung übernehmen.',['die Voraussetzung','zuständig','die Kompetenz']);
L('beschwerde-b2','B2','Professionell reagieren.','Du beantwortest eine Kundenbeschwerde lösungsorientiert.','Eine Antwort enthält Bezug, Verständnis, Erklärung, konkrete Lösung und Abschluss. Versprich nur, was gesichert ist. Mit Passiv formulierst du Vorgänge: Die Ware wird geprüft.','Wir bedauern die Verzögerung. Die fehlenden Teile werden morgen versendet.','Kundenmail: Von den zwölf bestellten Stühlen sind nur zehn angekommen. Zwei davon haben Kratzer. Wir benötigen alle Stühle bis Freitag.\nInterne Information: Zwei fehlende Stühle können morgen versendet werden. Für die beschädigten Stühle ist eine Abholung am Donnerstag möglich. Ein Ersatztermin muss noch geprüft werden.',[Q('Wie viele Stühle wurden geliefert?',['Acht','Zehn','Zwölf'],1,'Zehn sind angekommen; zwei davon sind beschädigt.'),Q('Was darfst du sicher zusagen?',['Alle Ersatzstühle kommen bis Freitag.','Die fehlenden Stühle werden morgen versendet.','Die beschädigten Stühle werden heute ersetzt.'],1,'Nur der Versand der fehlenden Stühle für morgen ist bestätigt.'),Q('Welche Passivform ist korrekt?',['Die Ware wird geprüft.','Die Ware hat geprüft.','Die Ware wird prüfen.'],0,'Vorgangspassiv: werden + Partizip II.')],'Antworte auf die Beschwerde. Berücksichtige beide Probleme und unterscheide bestätigte Schritte von offenen Fragen.','Sehr geehrte Frau Klein, vielen Dank für Ihre Nachricht. Wir bedauern die unvollständige Lieferung und die Schäden. Die zwei fehlenden Stühle werden morgen versendet. Für die beschädigten Stühle können wir eine Abholung am Donnerstag anbieten. Den Termin für die Ersatzlieferung prüfen wir noch und informieren Sie schnellstmöglich. Mit freundlichen Grüßen, Alex Marin',['die Beschwerde','die Verzögerung','die Abholung']);
L('forum-b2','B2','Im Betrieb mitreden.','Du verfasst einen begründeten Beitrag zu einer betrieblichen Veränderung.','Strukturiere deine Argumentation: Anlass – Position – Argumente mit Beispielen – Gegenseite – Vorschlag. Zweiteilige Konnektoren helfen: zwar … aber; einerseits … andererseits.','Einerseits spart das Zeit, andererseits fehlt der persönliche Austausch.','Ihre Firma plant, an zwei Tagen pro Woche Homeoffice anzubieten. Im Teamforum werden Meinungen gesammelt. Einige Aufgaben benötigen direkten Kundenkontakt. Andere Aufgaben lassen sich gut am Computer erledigen.',[Q('Welcher Vorschlag berücksichtigt beide Arbeitsbereiche?',['Alle müssen immer zu Hause arbeiten.','Homeoffice wird passend zu den Aufgaben abgestimmt.','Niemand darf darüber sprechen.'],1,'Aufgabenabhängige Absprachen berücksichtigen Kundenkontakt und Computerarbeit.'),Q('Welche Verbindung passt?',['Einerseits … andererseits','Entweder … aber','Zwar … oder'],0,'„Einerseits … andererseits“ stellt zwei Seiten gegenüber.'),Q('Welche Aussage enthält eine Begründung?',['Das finde ich gut.','Ich unterstütze den Vorschlag, weil dadurch lange Anfahrten entfallen.','Homeoffice ist ein Thema.'],1,'Der weil-Satz liefert ein konkretes Argument.')],'Schreibe einen Forumsbeitrag: eigene Position, zwei Argumente, ein Gegenargument und ein umsetzbarer Vorschlag.','Liebe Kolleginnen und Kollegen, ich begrüße die Möglichkeit zum Homeoffice. Dadurch sparen viele von uns Fahrtzeit und können konzentrierte Aufgaben in Ruhe erledigen. Allerdings muss der Kundenkontakt im Betrieb gesichert bleiben. Deshalb schlage ich vor, die Anwesenheit im Team abzustimmen und feste Erreichbarkeitszeiten festzulegen. Wie seht ihr das? Viele Grüße, Alex',['die Vereinbarung','der Vorteil','vorschlagen']);
L('loesungen-b2','B2','Ein Problem. Ein Plan.','Du klärst ein Problem und vereinbarst konkrete Maßnahmen.','Unterscheide Sofortmaßnahme und langfristige Lösung. Nutze Konditionalsätze: Falls …, könnten wir … . Halte fest: Wer macht was bis wann?','Falls die Lieferung ausfällt, könnten wir einen anderen Anbieter anfragen.','Für eine Veranstaltung morgen fehlen 30 Namensschilder. Der Lieferant kann erst übermorgen liefern. Ein Drucker ist vorhanden, passendes Papier gibt es im Bürobedarf. Eine Kollegin kann heute bis 16 Uhr helfen.',[Q('Welche Sofortmaßnahme ist sinnvoll?',['Bis übermorgen warten','Die Schilder selbst drucken','Die Veranstaltung ohne Rücksprache absagen'],1,'Drucker, Papierbeschaffung und Unterstützung ermöglichen eine rechtzeitige Lösung.'),Q('Falls das Papier rechtzeitig …, können wir drucken.',['ankommt','kommt an','ankommen'],0,'Im falls-Nebensatz steht das konjugierte Verb am Ende; „ankommen“ bleibt zusammen.'),Q('Welche Vereinbarung ist am präzisesten?',['Jemand kümmert sich.','Wir machen das später.','Ich kaufe bis 14 Uhr das Papier; du prüfst bis 15 Uhr die Namen.'],2,'Aufgaben, Zuständigkeiten und Fristen sind eindeutig.')],'Besprecht zu zweit die Situation. Vereinbart Sofortmaßnahmen und eine Idee, wie ihr das Problem künftig vermeidet.','Wir sollten zuerst die Namensliste prüfen. Ich besorge bis 14 Uhr das Papier. Du bereitest die Druckdatei vor. Danach drucken wir gemeinsam. Für künftige Veranstaltungen bestellen wir früher und prüfen die Lieferung zwei Tage vorher.',['die Maßnahme','die Frist','zuverlässig']);
const languages={de:'Nur Deutsch',ru:'Русский',uk:'Українська',ar:'العربية',fa:'فارسی',tr:'Türkçe',ro:'Română',zh:'中文'};
const dictionary={};
